/* Random-forest inference over the flat tables generated by src/export_c.py (rf_model.h).
 *
 * Node layout (struct of arrays, internal nodes only):
 *   rf_feat[i]  uint8   feature index
 *   rf_thr[i]   float or int16 (Q5.10) threshold; `x < thr` goes left (same as upstream
 *               emg_functions.get_predictions, and as emlearn)
 *   rf_left[i], rf_right[i]  uint16 child: bit 15 set -> leaf, low bits = class;
 *               otherwise index of an internal node, relative to the tree's root
 *   rf_roots[t] uint32 offset of tree t; bit 31 set -> the whole tree is one leaf
 * Hard majority vote, ties go to the lowest class index.
 */
#pragma once
#include <stdint.h>
#include "rf_model.h"

/* Returns the predicted class (0 .. RF_N_CLASSES-1). */
int rf_predict(const rf_value_t *x);

#if RF_INT16
/* float z-scored features -> Q5.10 int16 (round half to even, saturating). */
void rf_quantize(const float *in, int16_t *out, int n);
#endif
